20: PYTHON_VERSION_MINOR=$$section(PYTHON_VERSION, ., 1, 1)
21: 
22: !equals(PYTHON_VERSION, $${PYTHON_VERSION_MAJOR}.$${PYTHON_VERSION_MINOR}) {
23:   error("Failed to parse PYTHON_VERSION:\"$$PYTHON_VERSION\"")
24: } else {
25:   message(Using Python version $${PYTHON_VERSION})
26: }
27: 
28: # Python 3.x is required
29: equals(PYTHON_VERSION_MAJOR, 2) {
30:   error("Python >= 3.x is required")
31: }
32: 
33: contains(PKGCONFIG, "python.*"){
34: # If `pkg-config` is configured, use `qmake PKGCONFIG+=python3.10-embed CONFIG+=...`
35: # or `PKGCONFIG+=python2.7m`-like form for older versions,
36: # see `pkg-config --list-all | grep python` for details.
37: # This can help with GNU/Linux (including macOS with Homebrew), MSYS2/MinGW environment,
38: # and also with OpenEmbedded and other cross-builds
39:   CONFIG += link_pkgconfig
40:   PYTHON_PKGCONFIG = $$member($$unique($$find(PKGCONFIG, "python.*")), 1, 1)
41:   # add rpath
42:   PYTHON_LIBDIR = $$system($$pkgConfigExecutable() --libs-only-L $$PYTHON_PKGCONFIG)
43:   QMAKE_RPATHDIR += $$replace(PYTHON_LIBDIR,-L,)
44: } else:macx:isEmpty(PYTHON_DIR){
45:   # for macx you need to have the Python development kit installed as framework
46:   INCLUDEPATH += /System/Library/Frameworks/Python.framework/Headers
47:   LIBS += -F/System/Library/Frameworks -framework Python
48: } else:win32 {
49:   # for windows install a Python development kit or build Python yourself from the sources
50:   # Make sure that you set the environment variable PYTHON_PATH to point to your
51:   # python installation (or the python sources/header files when building from source).
52:   #
53:   # When using the prebuild Python installer, this will be:
54:   # set PYTHON_PATH = c:\Python310
55:   #
56:   # When using the python sources, this will be something like:
57:   # set PYTHON_PATH = c:\yourDir\Python-3.10.12\
58: 
59:   # check if debug or release
60:   CONFIG(debug, debug|release) {
61:     DEBUG_EXT = _d
62:   } else {
63:     DEBUG_EXT =
64:   }
65: 
66:   isEmpty(PYTHON_PATH):PYTHON_PATH=$(PYTHON_PATH)
67:   isEmpty(PYTHON_PATH)|!exists("$$PYTHON_PATH\\include") | !exists("$$PYTHON_PATH\\libs\\") {
68:      error("PYTHON_PATH must be set to correct folder with \\libs and \\include subfolders ")
69:   }
70: 
71:   INCLUDEPATH += $$shell_path($${PYTHON_PATH}/include)
72: 
73:   LIBS += $$shell_path(-L$${PYTHON_PATH}/libs)
74:   LIBS += -lpython$${PYTHON_VERSION_MAJOR}$${PYTHON_VERSION_MINOR}$${DEBUG_EXT}
75: 
76:   # Hack for "CONFIG+=testcase" and 'make check' to add python's dll to PATH
77:   deppath += $$shell_path($${PYTHON_PATH})
78: 
79: } else:unix {
