90:   QMAKE_CXXFLAGS += $$system($${PYTHON_CONFIG} --includes)
91:   PYTHON_LFLAGS = $$system($${PYTHON_CONFIG} --ldflags)
92:   QMAKE_LFLAGS += $${PYTHON_LFLAGS}
93:   # add rpath
