344:   _p->_initFlags = flags;
345: 
346:   if ((flags & PythonAlreadyInitialized) == 0) {
347:     Py_SetProgramName(const_cast<wchar_t*>(L"PythonQt"));
348:     if (flags & IgnoreSiteModule) {
349:       // this prevents the automatic importing of Python site files
350:       Py_NoSiteFlag = 1;
351:     }
352:     Py_Initialize();
353:   }
354: 
355:   // add our own python object types for qt object slots
356:   if (PyType_Ready(&PythonQtSlotFunction_Type) < 0) {
357:     std::cerr << "could not initialize PythonQtSlotFunction_Type" << ", in " << __FILE__ << ":" << __LINE__
358:               << std::endl;
359:   }
360:   Py_INCREF(&PythonQtSlotFunction_Type);
361: 
362:   if (PyType_Ready(&PythonQtSignalFunction_Type) < 0) {
363:     std::cerr << "could not initialize PythonQtSignalFunction_Type" << ", in " << __FILE__ << ":" << __LINE__
364:               << std::endl;
365:   }
366:   Py_INCREF(&PythonQtSignalFunction_Type);
367: 
368:   if (PyType_Ready(&PythonQtSlotDecorator_Type) < 0) {
369:     std::cerr << "could not initialize PythonQtSlotDecorator_Type" << ", in " << __FILE__ << ":" << __LINE__
370:               << std::endl;
371:   }
372:   Py_INCREF(&PythonQtSlotDecorator_Type);
373: 
374:   if (PyType_Ready(&PythonQtProperty_Type) < 0) {
375:     std::cerr << "could not initialize PythonQtProperty_Type" << ", in " << __FILE__ << ":" << __LINE__ << std::endl;
376:   }
377:   Py_INCREF(&PythonQtProperty_Type);
378: 
379:   PythonQtBoolResult_Type.tp_new = PyType_GenericNew;
380:   if (PyType_Ready(&PythonQtBoolResult_Type) < 0) {
381:     std::cerr << "could not initialize PythonQtBoolResult_Type" << ", in " << __FILE__ << ":" << __LINE__ << std::endl;
382:   }
