444: PythonQtObjectPtr PythonQtPrivate::checkAndRunCoroutine(const PythonQtObjectPtr& object)
445: {
446:   PythonQtObjectPtr result;
447:   if (!PyCoro_CheckExact(object)) {
448:     return result;
449:   }
450: 
451:   if (!_pyEnsureFuture) {
452:     std::cerr << "PythonQt: ensure_future not initialized" << std::endl;
453:     return PythonQtObjectPtr();
454:   }
455:   PyObject* args = PyTuple_New(1);
456:   PyObject* coro = object.object();
457:   Py_INCREF(coro);
458:   PyTuple_SetItem(args, 0, coro);
459:   PyObject* r = PyObject_CallObject(_pyEnsureFuture, args);
460:   result.setNewRef(r);
461:   if (_pyTaskDoneCallback) {
462:     PyObject* methodName = PyUnicode_FromString("add_done_callback");
463:     PyObject_CallMethodObjArgs(r, methodName, _pyTaskDoneCallback.object(), nullptr);
464:     Py_XDECREF(methodName);
465:   }
466:   Py_XDECREF(args);
467:   return result;
468: }
