479: void PythonQt::setRedirectStdInCallback(PythonQtInputChangedCB* callback, void* callbackData)
480: {
481:   if (!callback) {
482:     std::cerr << "PythonQt::setRedirectStdInCallback - callback parameter is NULL !" << std::endl;
483:     return;
484:   }
485: 
486:   PythonQtObjectPtr sys;
487:   PythonQtObjectPtr in;
488:   sys.setNewRef(PyImport_ImportModule("sys"));
489: 
490:   // Backup original 'sys.stdin' if not yet done
491:   if (!PyObject_HasAttrString(sys.object(), "pythonqt_original_stdin")) {
492:     PyObject_SetAttrString(sys.object(), "pythonqt_original_stdin", PyObject_GetAttrString(sys.object(), "stdin"));
493:   }
494: 
495:   in = PythonQtStdInRedirectType.tp_new(&PythonQtStdInRedirectType, nullptr, nullptr);
496:   ((PythonQtStdInRedirect*)in.object())->_cb = callback;
497:   ((PythonQtStdInRedirect*)in.object())->_callData = callbackData;
498:   // replace the built in file objects with our own objects
499:   PyModule_AddObject(sys.object(), "stdin", in);
500: 
501:   // Backup custom 'stdin' into 'pythonqt_stdin'
502:   Py_INCREF(in); // AddObject steals the reference, so increment it
503:   PyModule_AddObject(sys.object(), "pythonqt_stdin", in);
504: }
