596: void PythonQtPrivate::createPythonQtClassWrapper(PythonQtClassInfo* info, const char* package, PyObject* module)
597: {
598:   QByteArray pythonClassName = info->className();
599:   int nestedClassIndex = pythonClassName.indexOf("::");
600:   bool isNested = false;
601:   if (nestedClassIndex > 0) {
602:     pythonClassName = pythonClassName.mid(nestedClassIndex + 2);
603:     isNested = true;
604:   }
605: 
606:   PyObject* pack = module ? module : packageByName(package);
607:   PyObject* pyobj = (PyObject*)createNewPythonQtClassWrapper(info, pack, pythonClassName);
608: 
609:   if (isNested) {
610:     QByteArray outerClass = QByteArray(info->className()).mid(0, nestedClassIndex);
611:     PythonQtClassInfo* outerClassInfo = lookupClassInfoAndCreateIfNotPresent(outerClass);
612:     outerClassInfo->addNestedClass(info);
613:   } else {
614:     if (PyModule_AddObject(pack, info->className(), pyobj) == 0) {
615:       // since PyModule_AddObject steals the reference, we need a incref once more...
616:       Py_INCREF(pyobj);
617:     }
618:   }
619:   if (!module && package && strncmp(package, "Qt", 2) == 0) {
620:     // put all qt objects into Qt as well
621:     if (PyModule_AddObject(packageByName("Qt"), info->className(), pyobj) == 0) {
622:       // since PyModule_AddObject steals the reference, we need a incref once more...
623:       Py_INCREF(pyobj);
624:     }
625:   }
626:   info->setPythonQtClassWrapper(pyobj);
627: }
