629: PyObject* PythonQtPrivate::wrapQObject(QObject* obj)
630: {
631:   if (!obj) {
632:     Py_RETURN_NONE;
633:   }
634:   PythonQtInstanceWrapper* wrap = findWrapperAndRemoveUnused(obj);
635:   if (wrap && wrap->_wrappedPtr) {
636:     // uh oh, we want to wrap a QObject, but have a C++ wrapper at that
637:     // address, so probably that C++ wrapper has been deleted earlier and
638:     // now we see a QObject with the same address.
639:     // Do not use the old wrapper anymore.
640:     wrap = nullptr;
641:   }
642:   if (!wrap) {
643:     // smuggling it in...
644:     PythonQtClassInfo* classInfo = _knownClassInfos.value(obj->metaObject()->className());
645:     if (!classInfo || classInfo->pythonQtClassWrapper() == nullptr) {
646:       registerClass(obj->metaObject());
647:       classInfo = _knownClassInfos.value(obj->metaObject()->className());
648:     }
649:     wrap = createNewPythonQtInstanceWrapper(obj, classInfo);
650:     //    mlabDebugConst("MLABPython","new qobject wrapper added " << " " << wrap->_obj->className() << " " << wrap->classInfo()->wrappedClassName().latin1());
651:   } else {
652:     Py_INCREF(wrap);
653:     //    mlabDebugConst("MLABPython","qobject wrapper reused " << wrap->_obj->className() << " " << wrap->classInfo()->wrappedClassName().latin1());
654:   }
655:   return (PyObject*)wrap;
656: }
