658: PyObject* PythonQtPrivate::wrapPtr(void* ptr, const QByteArray& name, bool passOwnership)
659: {
660:   if (!ptr) {
661:     Py_RETURN_NONE;
662:   }
663: 
664:   PythonQtInstanceWrapper* wrap = findWrapperAndRemoveUnused(ptr);
665:   PythonQtInstanceWrapper* possibleStillAliveWrapper = nullptr;
666:   if (wrap && wrap->_wrappedPtr) {
667:     // we have a previous C++ wrapper... if the wrapper is for a C++ object,
668:     // we are not sure if it may have been deleted earlier and we just see the same C++
669:     // pointer once again. To make sure that we do not reuse a wrapper of the wrong type,
670:     // we compare the classInfo() pointer and only reuse the wrapper if it has the same
671:     // info. This is only needed for non-QObjects, since we know it when a QObject gets deleted.
672:     possibleStillAliveWrapper = wrap;
673:     wrap = nullptr;
674:   }
675:   if (!wrap) {
676:     PythonQtClassInfo* info = getClassInfo(name);
677:     if (!info) {
678:       // maybe it is a PyObject, which we can return directly
679:       if (name == "PyObject") {
680:         // do not increment its ref-count, it is the job of the slot returning the value
681:         // to ensure an extra ref on return.
682:         return (PyObject*)ptr;
683:       }
684: 
685:       // we do not know the metaobject yet, but we might know it by its name:
686:       if (_knownQObjectClassNames.find(name) != _knownQObjectClassNames.end()) {
687:         // yes, we know it, so we can convert to QObject
688:         QObject* qptr = (QObject*)ptr;
689:         registerClass(qptr->metaObject());
690:         info = _knownClassInfos.value(qptr->metaObject()->className());
691:       }
692:     }
693:     if (info && info->isQObject()) {
694:       QObject* qptr = (QObject*)ptr;
695:       // if the object is a derived object, we want to switch the class info to the one of the derived class:
696:       if (name != (qptr->metaObject()->className())) {
697:         info = _knownClassInfos.value(qptr->metaObject()->className());
698:         if (!info || (info->pythonQtClassWrapper() == nullptr)) {
699:           registerClass(qptr->metaObject());
700:           info = _knownClassInfos.value(qptr->metaObject()->className());
701:         }
702:       }
703:       wrap = createNewPythonQtInstanceWrapper(qptr, info);
704:       wrap->_ownedByPythonQt = passOwnership;
705:       //    mlabDebugConst("MLABPython","new qobject wrapper added " << " " << wrap->_obj->className() << " " << wrap->classInfo()->wrappedClassName().latin1());
706:       return (PyObject*)wrap;
707:     }
708: 
709:     // not a known QObject, try to wrap via foreign wrapper factories
710:     PyObject* foreignWrapper = nullptr;
711:     for (int i = 0; i < _foreignWrapperFactories.size(); i++) {
712:       foreignWrapper = _foreignWrapperFactories.at(i)->wrap(name, ptr);
713:       if (foreignWrapper) {
714:         return foreignWrapper;
715:       }
716:     }
717: 
718:     // not a known QObject, so try our wrapper factory:
719:     QObject* wrapper = nullptr;
720:     for (int i = 0; i < _cppWrapperFactories.size(); i++) {
721:       wrapper = _cppWrapperFactories.at(i)->create(name, ptr);
722:       if (wrapper) {
723:         break;
724:       }
725:     }
726: 
727:     if (info) {
728:       // try to downcast in the class hierarchy, which will modify info and ptr if it is successfull
729:       ptr = info->castDownIfPossible(ptr, &info);
730: 
731:       // if downcasting found out that the object is a QObject,
732:       // handle it like one:
733:       if (info && info->isQObject()) {
734:         QObject* qptr = (QObject*)ptr;
735:         // if the object is a derived object, we want to switch the class info to the one of the derived class:
736:         if (name != (qptr->metaObject()->className())) {
737:           registerClass(qptr->metaObject());
738:           info = _knownClassInfos.value(qptr->metaObject()->className());
739:         }
740:         wrap = createNewPythonQtInstanceWrapper(qptr, info);
741:         wrap->_ownedByPythonQt = passOwnership;
742:         //    mlabDebugConst("MLABPython","new qobject wrapper added " << " " << wrap->_obj->className() << " " << wrap->classInfo()->wrappedClassName().latin1());
743:         return (PyObject*)wrap;
744:       }
745:     }
746: 
747:     if (!info || info->pythonQtClassWrapper() == nullptr) {
748:       // still unknown, register as CPP class
749:       registerCPPClass(name.constData());
750:       info = _knownClassInfos.value(name);
751:     }
752:     if (wrapper && (info->metaObject() != wrapper->metaObject())) {
753:       // if we a have a QObject wrapper and the metaobjects do not match, set the metaobject again!
754:       info->setMetaObject(wrapper->metaObject());
755:     }
756: 
757:     if (possibleStillAliveWrapper && possibleStillAliveWrapper->classInfo()->inherits(info)) {
758:       wrap = possibleStillAliveWrapper;
759:       Py_INCREF(wrap);
760:     } else {
761:       wrap = createNewPythonQtInstanceWrapper(wrapper, info, ptr);
762:       wrap->_ownedByPythonQt = passOwnership;
763:     }
764:     //          mlabDebugConst("MLABPython","new c++ wrapper added " << wrap->_wrappedPtr << " " << wrap->_obj->className() << " " << wrap->classInfo()->wrappedClassName().latin1());
765:   } else {
766:     Py_INCREF(wrap);
767:     //mlabDebugConst("MLABPython","c++ wrapper reused " << wrap->_wrappedPtr << " " << wrap->_obj->className() << " " << wrap->classInfo()->wrappedClassName().latin1());
768:   }
769:   return (PyObject*)wrap;
770: }
