782: PythonQtInstanceWrapper* PythonQtPrivate::createNewPythonQtInstanceWrapper(QObject* obj, PythonQtClassInfo* info,
783:   void* wrappedPtr)
784: {
785:   // call the associated class type to create a new instance...
786:   PythonQtInstanceWrapper* result =
787:     (PythonQtInstanceWrapper*)PyObject_Call(info->pythonQtClassWrapper(), dummyTuple(), nullptr);
788: 
789:   result->setQObject(obj);
790:   result->_wrappedPtr = wrappedPtr;
791:   result->_ownedByPythonQt = false;
792:   result->_useQMetaTypeDestroy = false;
793: 
794:   if (wrappedPtr || obj) {
795: 
796:     // if this object is reference counted, we ref it:
797:     PythonQtVoidPtrCB* refCB = info->referenceCountingRefCB();
798:     if (refCB) {
799:       (*refCB)(wrappedPtr);
800:     }
801: 
802:     if (wrappedPtr) {
803:       _wrappedObjects.insert(wrappedPtr, result);
804:     } else {
805:       _wrappedObjects.insert(obj, result);
806:       if (obj->parent() == nullptr && _wrappedCB) {
807:         // tell someone who is interested that the qobject is wrapped the first time, if it has no parent
808:         (*_wrappedCB)(obj);
809:       }
810:     }
811:   }
812:   return result;
813: }
