815: PythonQtClassWrapper* PythonQtPrivate::createNewPythonQtClassWrapper(PythonQtClassInfo* info, PyObject* parentModule,
816:   const QByteArray& pythonClassName)
817: {
818:   PythonQtClassWrapper* result;
819: 
820:   PyObject* className = PyUnicode_FromString(pythonClassName.constData());
821: 
822:   PyObject* baseClasses = PyTuple_New(1);
823:   Py_INCREF((PyObject*)&PythonQtInstanceWrapper_Type);
824:   PyTuple_SET_ITEM(baseClasses, 0, (PyObject*)&PythonQtInstanceWrapper_Type);
825: 
826:   PyObject* typeDict = PyDict_New();
827:   PyObject* moduleName = PyObject_GetAttrString(parentModule, "__name__");
828:   PyDict_SetItemString(typeDict, "__module__", moduleName);
829: 
830:   PyObject* args = Py_BuildValue("OOO", className, baseClasses, typeDict);
831: 
832:   // set the class info so that PythonQtClassWrapper_new can read it
833:   _currentClassInfoForClassWrapperCreation = info;
834:   // create the new type object by calling the type
835:   result = (PythonQtClassWrapper*)PyObject_Call((PyObject*)&PythonQtClassWrapper_Type, args, nullptr);
836: 
837:   Py_DECREF(baseClasses);
838:   Py_DECREF(typeDict);
839:   Py_DECREF(moduleName);
840:   Py_DECREF(args);
841:   Py_DECREF(className);
842: 
843:   return result;
844: }
