1002:       dict = PyObject_GetAttrString(object, "__dict__");
1003:       globals = PyObject_GetAttrString(
1004:         PyImport_ImportModule(PyUnicode_AsUTF8(PyObject_GetAttrString(object, "__module__"))), "__dict__");
