1206:     object = lookupObject(module, objectname);
1207:     if (!object && type == CallOverloads) {
1208:       PyObject* dict = lookupObject(module, "__builtins__");
1209:       if (dict) {
1210:         object = PyDict_GetItemString(dict, QStringToPythonCharPointer(objectname));
1211:       }
1212:     }
1213:   }
1214: 
1215:   if (object) {
1216:     results = introspectObject(object, type);
1217:   }
1218:   PyErr_Clear();
1219:   return results;
