1222: QStringList PythonQt::introspectObject(PyObject* object, ObjectType type)
1223: {
1224:   QStringList results;
1225: 
1226:   if (type == CallOverloads) {
1227:     if (PythonQtSlotFunction_Check(object)) {
1228:       PythonQtSlotFunctionObject* o = (PythonQtSlotFunctionObject*)object;
1229:       results = o->m_ml->overloads();
1230:     } else if (PythonQtSignalFunction_Check(object)) {
1231:       PythonQtSignalFunctionObject* o = (PythonQtSignalFunctionObject*)object;
1232:       results = o->m_ml->overloads();
1233:     } else if (object->ob_type == &PythonQtClassWrapper_Type) {
1234:       PythonQtClassWrapper* o = (PythonQtClassWrapper*)object;
1235:       PythonQtSlotInfo* info = o->classInfo()->constructors();
1236:       if (info) {
1237:         results = info->overloads(/*skipReturnValue = */ true);
1238:       }
1239:     } else {
1240:       QString signature = _p->getSignature(object);
1241:       if (!signature.isEmpty()) {
1242:         results << signature;
1243:       } else {
1244:         PyObject* doc = PyObject_GetAttrString(object, "__doc__");
1245:         if (doc) {
1246:           QString docString = QString::fromUtf8(PyUnicode_AsUTF8(doc));
